import 'package:path/path.dart';import 'package:sqflite/sqflite.dart';
class LocalDatabase{LocalDatabase._();static final instance=LocalDatabase._();Database? _db;Future<Database> get db async=>_db??=await openDatabase(join(await getDatabasesPath(),'sensus.db'),version:1,onCreate:(d,v)async{await d.execute('CREATE TABLE inspections(id TEXT PRIMARY KEY, block_id TEXT NOT NULL, period INTEGER NOT NULL, row_number TEXT NOT NULL, bunch_count INTEGER, status TEXT NOT NULL, payload_json TEXT NOT NULL, updated_at TEXT NOT NULL)');await d.execute('CREATE TABLE sync_queue(id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, operation TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL)');});}
